WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (551::BIGINT, 'Tiene una forma muy rara de explicar, casi no se le entiende. Tarda demasiado en entregar las evaluaciones Utiliza material y presentaciones hechas con IA'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-07-04T00:00:00+00:00'::TIMESTAMPTZ, '7d6783f20ecbfc88f6b46c21322fed77721dcc1e546d0e10ff424df10a6d3a77'::TEXT, ARRAY[568]::BIGINT[]),
    (551::BIGINT, 'No sabe explicar, es muy desordenada y dura para entregar las evaluaciones'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-07-03T00:00:00+00:00'::TIMESTAMPTZ, '84f970675b9937572018b2c2eee99529cce2d4dd99e55429bf4fa7dc89769bcc'::TEXT, ARRAY[614]::BIGINT[]),
    (551::BIGINT, 'Es muy buena persona, tiene mucha paciencia y es amable, pero como profesora es muy mala. Las presentaciones que usa son hechas con IA y en general no sabe explicar, cuesta mucho entenderle. Explica lo más básico y lo difícil prácticamente no. Uno termina enseñándose solo, no la recomiendo.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2026-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'be13a9d9b5fb60c533cee50b064305c3424907239727082519dedd783aa7475f'::TEXT, ARRAY[568]::BIGINT[]),
    (551::BIGINT, 'Es buena persona, y si uno le pregunta trata de explicar varias veces, sin embargo sus clases son muy desordenadas y poco claras, en mi opinión no es la mejor profe, hace bastantes Quiz lo que ayuda en la nota, pero los exámenes los llego a revisar un asistente, casi que uno aprende solo o con tutor'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo']::TEXT[], '2026-01-05T00:00:00+00:00'::TIMESTAMPTZ, '84affa2eccec6d172dcbf5fc8b02c9b499c42c9227f462c3e9aec6b13f1f5768'::TEXT, ARRAY[614, 568]::BIGINT[]),
    (551::BIGINT, 'Enseñando no es muy buena, es mejor ser autodidacta y en general cuando yo lo lleve se veía que era muy desinteresada. Si bien pasé "bien" siento que no se me enseño lo suficiente, y la materia si es bastante importante. Si hay otro profe, mejor matricule con el otro'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-03T00:00:00+00:00'::TIMESTAMPTZ, '87632b19f3de338b010430c722f2eacc15521f0c5282e5bb964c1a48c5be76fa'::TEXT, ARRAY[2737]::BIGINT[]),
    (551::BIGINT, 'Las presentaciones que usa son malisimas, aunque me apasiona la materia no sabe explicar. Como cambiaron el programa no existen examenes de práctica. Casi toda la nota es de los exámenes y revisa durisimo. Solo sigue siendo profesora porque la ponen de jefa de la cátedra.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'f4513f53b9be2198706feb5e827d34f48961e682a2ef6c0c398d0522dbfc36f5'::TEXT, ARRAY[2737]::BIGINT[]),
    (551::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes']::TEXT[], '2025-07-23T00:00:00+00:00'::TIMESTAMPTZ, '98f6c01d22ea7d68d5fdcd7e36e4a26d1e19ba74d0f0ea702d0074b235bfd2c5'::TEXT, ARRAY[614, 568]::BIGINT[]),
    (551::BIGINT, 'La explicación deja que desear, pero da bastante material de apoyo y practicas y los quizes son bastante faciles'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-07-12T00:00:00+00:00'::TIMESTAMPTZ, 'c7f32abf016e03723996ffe5c67b5b881b488241f065439d7697899f82bbf874'::TEXT, ARRAY[568]::BIGINT[]),
    (551::BIGINT, 'Para primer ingreso la recomiendo. Muy buena profe, paciente, brinda ayuda y entiende los problemas. Yo solo en el último examen use las presentaciones, si son enrredadas, pero junto con lo visto en clase, uno logra repasar bien.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Brinda apoyo']::TEXT[], '2025-07-05T00:00:00+00:00'::TIMESTAMPTZ, '813fbc6a8d4f9d04cbe7dd84996548b9272af51e9a5088910e63ae5e2e2459e4'::TEXT, ARRAY[568]::BIGINT[]),
    (551::BIGINT, 'La profesora quiera ayudar, sin embargo, no es buena explicando y sus presentaciones son malas (parecen hechas por IA). Eso sí, brinda prácticas para los exámenes y algunos trabajos extras, además algunos quices y el proyecto son relativamente fáciles.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra']::TEXT[], '2025-07-04T00:00:00+00:00'::TIMESTAMPTZ, 'd76f43507504a6025678e583779fce1f4aaa8d162f95a699e9d8f50888f9f126'::TEXT, ARRAY[2737]::BIGINT[]),
    (551::BIGINT, 'Cuando quiere explica bien, se nota que le apasiona el curso, pero sus presentaciones son un fiasco, inservibles. Califica suave, aunque aveces califica medio raro.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas']::TEXT[], '2025-07-03T00:00:00+00:00'::TIMESTAMPTZ, 'fed8e753fa3c8bb1c69abc47da69971c69767a5e07fd1853bfe14342ed71e580'::TEXT, ARRAY[2737]::BIGINT[]),
    (551::BIGINT, 'Con decir que a un día del examen de reposición no tenía mi nota digo todo, es super desorganizada, no sabe explicar, es una incompetente total, no sé como llego a ser la directora de catedra.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Exámenes retadores']::TEXT[], '2025-06-27T00:00:00+00:00'::TIMESTAMPTZ, '02e4307b78d599754cd558a3a01ac18116fa156ddac729ce4d0ba70c672857c8'::TEXT, ARRAY[568]::BIGINT[]),
    (551::BIGINT, 'Pésima profesora, se enreda en todo, en el último parcial deja que los estudiantes den las materias en presentaciones de 10 minutos y no vuelve a tocar dichos temas, cuando vaya a matricular teoría y están Johnny Valverde y ella, lleve con Johnny, los exámenes son catedrados y se lo van a sonar.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'cfa0e6c77cb90ac646268e0d63be4b22365f64593a1a6c89cc0d275e941a33ea'::TEXT, ARRAY[2737]::BIGINT[]),
    (551::BIGINT, 'La peor profesora. Le regalan el sueldo prácticamente. No da nada de materia, prácticamente es como estudiar solo. Explica mal, se enreda o del todo no enseña. Más del 80% de la materia la dieron los estudiantes y ella ya veía la materia por vista. Siempre se equivoca revisando hasta los exámenes'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2025-06-05T00:00:00+00:00'::TIMESTAMPTZ, '0396d64625650522d8fdf165c004b331ee3bb67ada996878df93e2901be8e3dd'::TEXT, ARRAY[2737]::BIGINT[]),
    (551::BIGINT, 'Es buena profe para lab de quimica, no es tan dura como lo suelen ser los otros profes, la entrega de los cuadernos es por teams y los quices son por socrative, super faciles. En general si va entregando todo pasa super facil.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2024-11-08T00:00:00+00:00'::TIMESTAMPTZ, 'd4327cbb2c786584e101e0c6a7047b7897c0963c14cf25b904c17d64a4096655'::TEXT, ARRAY[567, 2738]::BIGINT[]),
    (551::BIGINT, 'No explica bien, se confunde con todo, no sabe ni donde esta parada y no sabe ni calificar. Imaginense que calidad de profesor es que no ha terminado el semestre y ya estoy haciendo esta reseña. Ademas preparese para clases aburridas y luego ir a su casa a aprender todo SOLO'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2024-10-16T00:00:00+00:00'::TIMESTAMPTZ, 'b8ee523162ae44a81c8ab06add5dd51b1b2aab25377b7210fa5676ece4ef6379'::TEXT, ARRAY[568]::BIGINT[]),
    (551::BIGINT, 'En que mundo explica claro? huyan de aqui, si no fuera por el cuaderno del cole yo me hubiera quedado, explica super enredado, el unico beneficio es que siempre hace quizzes virtuales y en grupos fuera de tiempo de clase.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2024-09-20T00:00:00+00:00'::TIMESTAMPTZ, 'f401b5cace2802146cbab6b1fb62ee8595ac278e2eb0ec907d9a8efb4e0651d7'::TEXT, ARRAY[568]::BIGINT[]),
    (551::BIGINT, 'Explica rápido y claro, pero se enreda a veces, parece dormida en algunas clases, la libreta se entrega por Teams, algo incomodo, pero los quices son fáciles y se hacen por Socrative, recomendada para primer ingreso, es comprensiva con los errores y fallos que uno puede tener.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2024-09-09T00:00:00+00:00'::TIMESTAMPTZ, '0574f77948a4d45ae1582f5211b110d346eec7965ea5deb4da50add77db4de8e'::TEXT, ARRAY[567]::BIGINT[]),
    (551::BIGINT, 'La profesora es bastante conocida en el tema, de que esta capacitada lo esta, pero no explica de formas claras ni concisas y hace muchisimo enredo de vez en cuando. Incluso, si uno no pregunta cosas, el tema no se ve. Generalmente la profesora siempre da este curso, entonces sea autodidacta.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Da crédito extra', 'Aspectos de calificación claros']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'b7a55ba802772d4d1fdb0007209324aacb8eca34ffca0440738fc0ad692b993e'::TEXT, ARRAY[2737]::BIGINT[]),
    (551::BIGINT, 'Si te tiene que explicar los procedimientos 3 veces lo hace, tiene demasiada paciencia, aunque aveces se vuelve confusa la forma de explicar ciertas cosas, los avances del cuaderno se entregan via teams y no califica duro los informes, si usted es aplicado se pasa fácil.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'ecba31879256367daa8780731562ed82a4ffc74383c22651f2050066682e75bc'::TEXT, ARRAY[567]::BIGINT[]),
    (551::BIGINT, 'La profe es una excelente química, realmente sabe mucho, pero para explicar le cuesta bastante y para un curso como orgánica que es tan importante no es la indicada, las clases no siguen un hilo conductor entonces uno termina más enredado de como inicio, y bueno esta química es bastante complicada'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Da crédito extra']::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, '85e118c9d4ef91005334133ecb9840a25b2e1a3e24c1b1624775b5d8f4277fac'::TEXT, ARRAY[2737]::BIGINT[]),
    (551::BIGINT, 'La profesora sabe de lo que habla, pero no sabe explicar necesariamente bien durante la clase. Se encarga de subir toda la materia y de ser muy clara con todo pero si debes ser autodidacta. Sin embargo, ella es muy consciente y considerada con los estudiantes ya que da puntos extra por las buenas'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2024-01-23T00:00:00+00:00'::TIMESTAMPTZ, '494a0a45415284f9ebf7d5a9ced6b51abd4cd03b0637a3e58251f5a2b0e68cfb'::TEXT, ARRAY[614]::BIGINT[]),
    (551::BIGINT, 'Muy buena persona, hace mucha práctica. Es muy comprensiva y le importa que todos pasen. Igual esta materia se las trae por lo que es importante estudiar independientemente también. VITAL, poner mucha atención.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2024-01-17T00:00:00+00:00'::TIMESTAMPTZ, 'b71b10bc184d40da740ceb242cba163b65978e928b018000f90853a0bb6f2d8d'::TEXT, ARRAY[614]::BIGINT[]),
    (551::BIGINT, 'Esta profesora va a explicar la materia de la manera más confusa que exista, los ejercicios que lleva planteados a la clase tienen errores, le va a tocar aprender solo. Los quices eran virtuales y dio puntos extra que ayudaron a más de uno a pasar el curso'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Da crédito extra']::TEXT[], '2024-01-11T00:00:00+00:00'::TIMESTAMPTZ, '31c9f66ed51bcee65c900d588f134009909051ea52bd2caa4b298634f44e5b35'::TEXT, ARRAY[614]::BIGINT[]),
    (551::BIGINT, 'Se nota que sabe la materia pero la forma en que la explica no es muy enganchante. Los quices que hace son de un nivel más complicado de lo que enseña en clases. Ella está muy dispuesta para ayudar pero en cuanto a entender la materia va a tener que ser autodidacta.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da crédito extra']::TEXT[], '2023-12-21T00:00:00+00:00'::TIMESTAMPTZ, '3f48b60e7280facdea02778c1fb4d83794dc372bce988812a73d53b17408632a'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (551::BIGINT, 'Profesora complicada para entenderle la verdad, se enreda muchísimo para explicar, su explicación no es suficiente para los examenes y los examenes cortos son largos así que prepárese, le recomiendo que asista a clases y que se note su participación, ayuda al final y si ve al grupo mal.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2023-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'aba93a27eea3e2eb81a6d4ce632f519491436c321af740d2e133dba4162890c9'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (551::BIGINT, 'Si matriculan con ella tienen que saber que hay que ser 100% autodidacta porque ella no explica cómo se debe, se enreda mucho y no abarca toda la materia del examen. Hizo quices extra para subir las notas porque eran muy malas. Es muy buena personas pero una pésima profesora'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'dd2faf3b0b34af1d03985a0546644cb07aa257e30c0af57ec3dd7a791c93f4fe'::TEXT, ARRAY[614]::BIGINT[]),
    (551::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-11-14T00:00:00+00:00'::TIMESTAMPTZ, 'd8508947437394af1608c38f8a76a612a57b666e568ddf17595ada00441047bb'::TEXT, ARRAY[614]::BIGINT[]),
    (551::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2023-11-12T00:00:00+00:00'::TIMESTAMPTZ, 'cf52224d53bc049c6657dffcc12b8080e26491bd02910b59e1db416bd0f3ddcd'::TEXT, ARRAY[613, 2738]::BIGINT[]),
    (551::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-11-01T00:00:00+00:00'::TIMESTAMPTZ, '3226675231653cd9474c9d1aff1b97c0c0c050f45bfeabc08f4fff249edcbe81'::TEXT, ARRAY[614]::BIGINT[]),
    (551::BIGINT, 'Hace quiz virtuales pero su explicación de la materia no es clara'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-10-24T00:00:00+00:00'::TIMESTAMPTZ, '6033a17ff913837597f9bf1c679a55c338db5e825c6b2e78531751d140923464'::TEXT, ARRAY[614, 568]::BIGINT[]),
    (551::BIGINT, 'La profe sabe bastante de la materia pero no sabe explicar, así que preparase para estudiar del libro y aprender viendo videos en YouTube. No hace quices y califica bastante suave las tareas y el proyecto (obviamente si están bien hechos). Los examenes sí los califica duro, así que no se confíen.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Requiere mucha lectura', 'Brinda apoyo']::TEXT[], '2023-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'fdaefa26e426032a1bcf2ac940baaaa397bd089845097e887799145feaf96724'::TEXT, ARRAY[2737]::BIGINT[]),
    (551::BIGINT, 'Al inicio del curso parece ser buena, pero es porque es la parte más sencilla, sin embargo, aún así le va a ir mejor estudiando del libro que yendo a las clases de ella. Para consulta es pésima, llega tarde, dura bastante revisando exámenes, se le olvidan las cosas, etc. Malas clases en general.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2023-06-24T00:00:00+00:00'::TIMESTAMPTZ, '07cfc52956a1fd999046185df9058834137101b192f8912e77ec618b565fab06'::TEXT, ARRAY[2737]::BIGINT[]),
    (551::BIGINT, 'Excelente profesora en el área de teoría de química orgánica, el curso es bastante complicado, pero ella se preocupa porque los estudiantes entiendan y brinda material y apoyo extra de ser necesario además de actividades en clase para reforzar el conocimiento.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-23T00:00:00+00:00'::TIMESTAMPTZ, '407a4bdf5018feea0163098f460b2d231800dc5dc6d7988ba6ef55f8623107ee'::TEXT, ARRAY[2737]::BIGINT[]),
    (551::BIGINT, 'La profe sabe mucho, pero no es la mejor explicando los temas. Es un poco superficial y asume que los estudiantes ya saben todo del tema a partir de una explicación breve. Los examenes del curso son complejos y hay que estudiar bastante por su cuenta. Las clases suelen ser cortas.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Muchos proyectos grupales']::TEXT[], '2023-06-20T00:00:00+00:00'::TIMESTAMPTZ, '6398eeb58da153ca208960030b95175f3faa29a9a83e20ec9a03756a74b973be'::TEXT, ARRAY[2737]::BIGINT[]),
    (551::BIGINT, 'La profe sabe demasiado los temas que da pero no los explica bien y es confuso, lo hace todo muy rápido y superficial. Es pésima para consulta, contesta tiempo después y no acepta los reclamos fundamentados. Con ella hay que ser muy autodidacta.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2023-06-18T00:00:00+00:00'::TIMESTAMPTZ, '56fe782276288554880b93ce2d3e88c57262a822ce52b272c2c5b3f6053c0b9f'::TEXT, ARRAY[2737]::BIGINT[]),
    (551::BIGINT, 'Sabe mucho de los temas, pero es pésima para explicar, solo menciona el aspecto más básico para después preguntar en exámenes o quices algo super complicado, tampoco es útil a la hora de responder dudas, ni acepta reclamos que esten bien fundamentados.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2023-05-01T00:00:00+00:00'::TIMESTAMPTZ, '6303168516c81fe65a112481b6156a490d0381d88564c9da86066ee86814330b'::TEXT, ARRAY[2737]::BIGINT[]),
    (551::BIGINT, 'Se nota que sabe muchísimo y siempre está dispuesta a responder dudas las veces que uno ocupe. El curso es en sí es súper complejo y amplio, entonces a veces se va por las ramas, se enreda o va muy rápido, pero si uno le pone bastante atención y hace preguntas, le va bien.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2023-01-28T00:00:00+00:00'::TIMESTAMPTZ, '0d9b88306c0c4ecdc96cfb045c35e9322e2f998a3b7794dc90dd3a68797a32e6'::TEXT, ARRAY[2737]::BIGINT[]),
    (551::BIGINT, 'Me pareció una profe bastante buena, las clases son bastante claras, realiza una explicación de la teoría y de lo que se va a realizar antes de cada práctica. Es importante estudiar para los exámenes cortos. Me parece que no califica muy duro por lo que es relativamente fácil pasar el curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2022-12-30T00:00:00+00:00'::TIMESTAMPTZ, '777ce8f46e34029ee8411cb48fd21f059257b317597235bfe614b5cc1b557e61'::TEXT, ARRAY[613]::BIGINT[]),
    (551::BIGINT, 'El curso tiene materia bastante compleja de entender y la profesora no ayuda mucho a comprenderla. La profesora es una buena persona, pero como docente no es muy buena, cuesta mucho seguirle el hilo. No enseña toda la materia, o lo hace de forma muy superficial, por lo que toca estudiar uno solo.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-08T00:00:00+00:00'::TIMESTAMPTZ, 'dde13764d7f75f1800adb1d750e9d8c5d6ace6233451f7e0e0f4426ce2be909a'::TEXT, ARRAY[2737]::BIGINT[]),
    (551::BIGINT, 'La profe se nota que sabe, sin embargo, no tiene la capacidad de enseñar correctamente, se enreda mucho y ve la materia solo de forma superficial. Le pedi ayuda en una ocasión y me dejo en visto.Pase el curso estudiando yo sola, ya que a ella no se le entendia nada.'::TEXT, 8.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2022-07-24T00:00:00+00:00'::TIMESTAMPTZ, '974080b7e180e195007d4d3703ee2ab93c1d3e19d4329ccdb011766689f5e0c2'::TEXT, ARRAY[2737]::BIGINT[]),
    (551::BIGINT, 'Es buena profesora, a veces un poquito desorganizada pero en general muy bien, ella se preocupa porque usted entienda bien todo y le va a resolver cualquier duda, muy felixible con la entrega de las tareas. Califica duro los informes.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'f289ea5db145484963925c2a791febfda2ff47e43cacb03c500b3fdbb31ae3d8'::TEXT, ARRAY[567, 2738]::BIGINT[]),
    (551::BIGINT, 'Para un curso tan difícil como lo es orgánica, no la recomiendo porque usted no va a aprender mucho si no es autodidacta. El material que da es super confuso y muchas veces no sirve, por dicha existe el libro. Al menos sí es buena persona y comprensiva.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Brinda apoyo']::TEXT[], '2022-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'a330384f8ba5a56ac181d736b5841983fe037bb008dabe62a64d47ce0a30ce46'::TEXT, ARRAY[2737]::BIGINT[]),
    (551::BIGINT, 'El curso de por sí es difícil y ella lo hace algo confuso. Se va por las ramas, explica de manera superficial, es desordenada con el cronograma. Sin embargo, brinda mucha ayuda si se le pide, es flexible con las fechas de entrega y es muy amable y comprensiva.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2022-06-17T00:00:00+00:00'::TIMESTAMPTZ, '9285130b16350b3885bb9a3ec3eff43490c010507a84c46e7cdfeecff52d32f4'::TEXT, ARRAY[2737]::BIGINT[]),
    (551::BIGINT, 'La mae sabe mucho, es buena profesional pero cuando da la clase tiende a irse por las ramas, comienza a hablar sobre algo y terminamos en otra cosa totalmente diferente y esto da pie a que uno se enrede y cuando uno le pregunta si ayuda mucho pero la verdad es que el curos tampoco ayuda.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2022-06-09T00:00:00+00:00'::TIMESTAMPTZ, '662ace86a32bf8ba92cd95e6eaf618455459b2ecde7fe52b9b73bd80e222f372'::TEXT, ARRAY[2737]::BIGINT[]),
    (551::BIGINT, 'Muy buena profe. Es muy comprensiva y está dispuesta a dar más chance de entregar las cosas. El curso se pasa fácil, los informes no los revisa muy rudo y los exámenes cortos no son difíciles. Siempre atiende dudas y se asegura de que todo esté claro. Si tiene la oportunidad, matricule con ella.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-05-18T00:00:00+00:00'::TIMESTAMPTZ, 'fad5e0596c2631f05594ce0a4d442414560ead7b0eaaadc0e7aa1913c322f4d1'::TEXT, ARRAY[567, 2738]::BIGINT[]),
    (551::BIGINT, 'Explica de manera muy aburrida, no explica bien, solo lo superficial de la materia x lo que no se entiende bien y no siguió el cronograma. Lo único bueno sería que si pides ayuda te contesta y atrasa la entrega de las tareas si lo necesitas. Matriculen con Isaac en lugar de ella'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2022-05-04T00:00:00+00:00'::TIMESTAMPTZ, '93b360984401c4887e8407644eb62b85aea913fccd0d2ec3f0092f220d6127a3'::TEXT, ARRAY[2737]::BIGINT[]),
    (551::BIGINT, 'Si piensa matricular con ella matriculé con algún compañer@ que trabaje bien, ya que deja realizar los informes, cuestionarios y quizzes en parejas. Califica todos los informes.Explica muy bien, pero cuesta contactar por si tienes alguna duda. La recomiendo si va a dedicarle al curso.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2021-11-28T00:00:00+00:00'::TIMESTAMPTZ, '343c75ebb21c2f8b571b5f3b619745ce5eb83a140a10fd3cdae78f7d5a28c5a6'::TEXT, ARRAY[613, 2738]::BIGINT[]),
    (551::BIGINT, 'La profe es muy pura vida, no lo dude'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-16T00:00:00+00:00'::TIMESTAMPTZ, 'cf6bbbb4befcf51f55943b49f397fb810e540b38ec4bb6dfd69a379bde5a97ac'::TEXT, ARRAY[567, 2738]::BIGINT[]),
    (551::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, 'fcbae4edab5fbb7d1f0ea10c6d429e57c3d258445499dacde2aa13bf4e9b502b'::TEXT, ARRAY[567]::BIGINT[]),
    (551::BIGINT, 'Con ella se pasa de manera sencilla el curso. Se preocupa por el estudiante, matricule sin dudar. :))'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2021-07-05T00:00:00+00:00'::TIMESTAMPTZ, 'eeb2a0c9b2ed2e72c6135786f8abc15b5fe2514e326efc433b5d38152ffbf42c'::TEXT, ARRAY[567, 2738]::BIGINT[]),
    (551::BIGINT, 'Un amor de profesora, matricule sin dudar!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-04-09T00:00:00+00:00'::TIMESTAMPTZ, 'ad5c9de1e09963e2801cdffa0e600c3402f2e048c4125993d6f2e5fe8ddbe6dd'::TEXT, ARRAY[567, 2738]::BIGINT[]),
    (551::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Inspirador']::TEXT[], '2021-02-03T00:00:00+00:00'::TIMESTAMPTZ, '4b65086f4bb0564c866532935bbcbabd43c024f32478dd49ed0294ff688349e8'::TEXT, ARRAY[613]::BIGINT[]),
    (551::BIGINT, 'Re fácil con ella, metalo sin miedo'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-29T00:00:00+00:00'::TIMESTAMPTZ, '838541c6c65c3f29e70f1b207a774db0bf3e08dfc3a4a349a76d0d324ad64aa9'::TEXT, ARRAY[2737]::BIGINT[]),
    (551::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Aspectos de calificación claros']::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, 'ee600227278b29ac81df3ea540d59a2fb75d4ec420e96c279522ace260b94fdf'::TEXT, ARRAY[2737]::BIGINT[]),
    (551::BIGINT, 'Esta profe es lo mejor para llevar Orgánica, es un curso super pesado pero la profe lo hace ameno. Hace curvas en los quices y es sumamente comprensiva, no presiona y ayuda con lo que puede. El curso virtual es un amor, super recomendada.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Muchos proyectos grupales']::TEXT[], '2020-08-07T00:00:00+00:00'::TIMESTAMPTZ, '54a13e36a82f64d510ef44675e37fdca77432444d806c1879255850c409eef8d'::TEXT, ARRAY[2737]::BIGINT[]),
    (551::BIGINT, 'Muy buena profe, recomendada si tiene que llevar el curso virtual, demasiado comprensiva, ayuda bastante, nada más de ponerle mucho a los quices, los cuales no son tan rudos. Las clases las prepara con presentaciones anteriormente por lo que explica de manera ordenada.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-01T00:00:00+00:00'::TIMESTAMPTZ, 'acb5cfbe45d8afec1d4a87a71907b163f298fadc8a019c993ec31417dc618b8a'::TEXT, ARRAY[2737]::BIGINT[]),
    (551::BIGINT, 'Súper buena profe, recomendada si tiene que llevar el curso virtual, demasiado comprensiva, ayuda bastante, nada más de ponerle mucho a los quices, los cuales no son tan rudos'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-07-30T00:00:00+00:00'::TIMESTAMPTZ, 'fb80b7ef1d1e68198e098091e3b54e781b0dc095e09cd24cb5f7e10fea655a71'::TEXT, ARRAY[2737]::BIGINT[]),
    (551::BIGINT, 'Califica super suave, las quices son online fáciles y no pide la libreta, el curso es regalado'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-12-02T00:00:00+00:00'::TIMESTAMPTZ, '74e61a953570717456e8854e5559f504ec540d45c78703eb1e01dbbfb64f7fab'::TEXT, ARRAY[613]::BIGINT[]),
    (551::BIGINT, 'La profe es muy simpática, trata de ayudarlo a uno en lo más posible. El curso es muy pesado por sí solo, hay que ponerle bastante. Se enreda al explicar, no domina muy bien la materia.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-12-02T00:00:00+00:00'::TIMESTAMPTZ, '29a84da6963b5ed1049a60901792da1f51f5673f8287ae99a4079995704f573c'::TEXT, ARRAY[2737]::BIGINT[]),
    (551::BIGINT, 'La profe es muy buena gente, la clase de laboratorio era bastante corta, revisa justos los informes, envia las pruebas cortas para hacerlas en la casa.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Inspirador']::TEXT[], '2019-11-26T00:00:00+00:00'::TIMESTAMPTZ, '3f151cdc98f4290e0ae6d31b3900e651645ae387d55c29ac57272c47277b4fe4'::TEXT, ARRAY[613, 2738]::BIGINT[]),
    (551::BIGINT, 'Es súper simpática, un amor de persona. Explica bien la materia aunque el curso sigue siendo sumamente pesado por como es en sí. Intenta ayudar al estudiante y de facilitarle la mayor cantidad de herramientas posible. Es de esos profes que le sacan una sonrisa a uno. 100% recomendada.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2019-11-26T00:00:00+00:00'::TIMESTAMPTZ, '546b6b1ab488bb56f47b52ff07305e7663fee4aa8866a2feefa55be64b14c455'::TEXT, ARRAY[2737]::BIGINT[]),
    (551::BIGINT, 'Así de simple: ojalá todos los profes fueran como ella.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-28T00:00:00+00:00'::TIMESTAMPTZ, '1c05991a6691958868f28c7b13c2e66d12af9ef150397ff7272d57c3f8661bfb'::TEXT, ARRAY[567]::BIGINT[]),
    (551::BIGINT, 'Ventaja: Hace quices fáciles pero los informes los califica duro'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-26T00:00:00+00:00'::TIMESTAMPTZ, '824f3961de0ffb68c6e2aa858c740de6aa846c16d0f54eea0e624a9f7e958886'::TEXT, ARRAY[567, 2738]::BIGINT[]),
    (551::BIGINT, 'Simplemente la mejor. Bella persona, no se molesta si uno le pregunta algo que ya explicó y lo vuelve a explicar, es muy clara su manera de dar la clase. Los quices son virtuales, y por ende muy fáciles de pasar si se hacen con compañeros.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, '5de6d6c9f8f087fda37abedc5b575753df22442871b6952cc861b1c5a15ddf1a'::TEXT, ARRAY[567, 2738]::BIGINT[]),
    (551::BIGINT, 'es una buena persona, ella ayuda si no le da tiempo de terminar los informes(los puede entregar el siguiente día), los quices son en línea para hacer en la casa y son un poco complicados, explíca el experimento antes de hacerlo, aclara bien las dudas'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'f9489482416d301bebb139df3651e0291300039a4e46478fb2a232ad2ed0eb63'::TEXT, ARRAY[567, 2738]::BIGINT[]),
    (551::BIGINT, 'Es buena profe,explica al inicio como hacer el experimento y luego lo deja a uno hacerlo a su velocidad.Los quiz son en línea.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'd3f92ca04b090dd1acd45a8d4fef44fca61128dd50101dd509787d5eff48e035'::TEXT, ARRAY[567]::BIGINT[]),
    (551::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-21T00:00:00+00:00'::TIMESTAMPTZ, '163aebeaf9672b4aac65c9f3e6182a85fd359d05539d7cf47e95330b13e81e89'::TEXT, ARRAY[567]::BIGINT[]),
    (551::BIGINT, 'Excelente profe, ayuda mucho a los estudiantes. Clases dinámicas y entretenidas. Los qüices son un poco rudos. 100% recomendada.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-17T00:00:00+00:00'::TIMESTAMPTZ, '2acb6846504f49a175fea68244d642a29037a6a89acb4b72f9ef6d287611bc17'::TEXT, ARRAY[567]::BIGINT[]),
    (551::BIGINT, 'Los exámenes cortos (quices) los hace por medio de la computadora y son muy confusos(uno no sabe por que esta mal). Ayuda en clase, explica bien y es respetuosa'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2018-06-11T00:00:00+00:00'::TIMESTAMPTZ, '5162d09797785f846e28f27a2df5f7e6d8341e6f15c02ca84ba3441941f5be9e'::TEXT, ARRAY[567]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
